SELECT assert_true((SELECT count(*)=1 FROM legacy_push l JOIN push_outbox p ON p.id=l.id AND p.status=l.status AND p.body=l.body AND p.accounting_notification_id=l.related_entity_id),'existing canonical outbox receipt gains FK without resend or status change');
SELECT assert_true((SELECT count(*)=4 FROM push_outbox p JOIN historical_push_expected e ON e.notification_id=p.accounting_notification_id WHERE p.status='skipped' AND p.failure_reason='historical_gap_receipt'),'narrow historical backfill is idempotent and creates only four skipped receipts');
SELECT assert_true((SELECT count(*)=4 FROM notifications n JOIN historical_push_expected e ON e.notification_id=n.id) AND (SELECT count(*)=4 FROM accounting_invoice_deliveries d JOIN historical_push_expected e ON e.invoice_id=d.invoice_id),'historical backfill does not create extra invoices messages or in-app notifications');
BEGIN;
SELECT fixture_transfer(u(901),'20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM push_outbox p JOIN notifications n ON n.id=p.accounting_notification_id JOIN accounting_invoice_deliveries d ON d.notification_id=n.id JOIN settlement_invoices i ON i.id=d.invoice_id WHERE i.source_ledger_id=u(901)),'canonical outbox waits until actual delivery link is present at commit');
COMMIT;
SELECT assert_true((SELECT count(*)=1 FROM push_outbox p JOIN accounting_invoice_deliveries d ON d.notification_id=p.accounting_notification_id JOIN settlement_invoices i ON i.id=d.invoice_id WHERE i.source_ledger_id=u(901) AND p.status='pending'),'canonical invoice bypasses full generic queue exactly once');
SELECT fn_deliver_accounting_invoice((SELECT id FROM settlement_invoices WHERE source_ledger_id=u(901)));
SELECT assert_true((SELECT count(*)=1 FROM push_outbox p JOIN accounting_invoice_deliveries d ON d.notification_id=p.accounting_notification_id JOIN settlement_invoices i ON i.id=d.invoice_id WHERE i.source_ledger_id=u(901)),'invoice delivery replay cannot duplicate the push receipt');
INSERT INTO notifications(user_id,type,title,message) VALUES('10000000-0000-0000-0000-000000000002','system','Capped ordinary message','Not a canonical invoice');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM push_outbox WHERE title='Capped ordinary message'),'ordinary notification caps remain enforced');
SELECT assert_true((SELECT push_enabled=false FROM notification_preferences WHERE user_id='10000000-0000-0000-0000-000000000002'),'enqueue does not change user push consent or bypass dispatcher preferences');
DO $$ BEGIN
 INSERT INTO notifications(user_id,type,title,message,data) VALUES('10000000-0000-0000-0000-000000000002','accounting_invoice','Forged','Fake','{"kind":"accounting_invoice","invoice_id":"00000000-0000-0000-0000-000000000901"}');
 SET CONSTRAINTS trg_accounting_push_after_delivery IMMEDIATE;
 RAISE EXCEPTION 'FAIL forged accounting metadata bypassed provenance';
 EXCEPTION WHEN check_violation THEN RAISE NOTICE 'PASS: forged metadata without actual delivery link is rejected';
END $$;
DO $$ BEGIN
 SET CONSTRAINTS trg_accounting_push_after_delivery IMMEDIATE;
 PERFORM fixture_transfer(u(902),'20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001');
 RAISE EXCEPTION 'FAIL early constraint silently lost canonical push';
 EXCEPTION WHEN check_violation THEN RAISE NOTICE 'PASS: premature constraint mode fails transaction instead of losing push';
END $$;
SELECT assert_true(NOT EXISTS(SELECT 1 FROM chip_ledger WHERE id=u(902)) AND NOT EXISTS(SELECT 1 FROM fixture_effects WHERE id=u(902)),'premature check rolls back the linked transfer effect');
CREATE FUNCTION fixture_reject_canonical_push() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.accounting_notification_id IS NOT NULL THEN RAISE EXCEPTION 'forced outbox failure'; END IF; RETURN NEW; END $$;
CREATE TRIGGER fixture_reject_canonical_push BEFORE INSERT ON push_outbox FOR EACH ROW EXECUTE FUNCTION fixture_reject_canonical_push();
DO $$ BEGIN
 PERFORM fixture_transfer(u(903),'20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001');
 SET CONSTRAINTS trg_accounting_push_after_delivery IMMEDIATE;
 RAISE EXCEPTION 'FAIL outbox failure did not abort';
 EXCEPTION WHEN raise_exception THEN IF SQLERRM<>'forced outbox failure' THEN RAISE; END IF; RAISE NOTICE 'PASS: canonical outbox failure propagates';
END $$;
DROP TRIGGER fixture_reject_canonical_push ON push_outbox;
SELECT assert_true(NOT EXISTS(SELECT 1 FROM chip_ledger WHERE id=u(903)) AND NOT EXISTS(SELECT 1 FROM settlement_invoices WHERE source_ledger_id=u(903)) AND NOT EXISTS(SELECT 1 FROM fixture_effects WHERE id=u(903)),'outbox failure rolls back invoice and linked financial effect');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM notifications WHERE data->>'source_ledger_id'=u(903)::text) AND NOT EXISTS(SELECT 1 FROM social_messages WHERE media_metadata->>'source_ledger_id'=u(903)::text),'outbox failure also rolls back message and notification');
BEGIN;
SELECT fixture_transfer(u(904),'20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001');
UPDATE accounting_invoice_deliveries SET delivery_mode='weekly_detail' WHERE invoice_id=(SELECT id FROM settlement_invoices WHERE source_ledger_id=u(904));
UPDATE notifications SET type='accounting_invoice_detail' WHERE data->>'source_ledger_id'=u(904)::text;
COMMIT;
SELECT assert_true((SELECT count(*)=1 FROM push_outbox p JOIN accounting_invoice_deliveries d ON d.notification_id=p.accounting_notification_id JOIN settlement_invoices i ON i.id=d.invoice_id WHERE i.source_ledger_id=u(904) AND p.status='skipped' AND p.failure_reason='accounting_archived_detail'),'detail archived before commit never becomes a device push');
CREATE FUNCTION fixture_old_notification() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN NEW.created_at:=now()-interval '1 hour'; RETURN NEW; END $$;
CREATE TRIGGER fixture_old_notification BEFORE INSERT ON notifications FOR EACH ROW EXECUTE FUNCTION fixture_old_notification();
SELECT fixture_transfer(u(905),'20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001');
DROP TRIGGER fixture_old_notification ON notifications;
SELECT assert_true((SELECT count(*)=1 FROM push_outbox p JOIN accounting_invoice_deliveries d ON d.notification_id=p.accounting_notification_id JOIN settlement_invoices i ON i.id=d.invoice_id WHERE i.source_ledger_id=u(905) AND p.status='skipped' AND p.failure_reason='accounting_historical_notification'),'old canonical notification leaves explicit skipped receipt instead of silentdrop');
SELECT assert_true(refuses('INSERT INTO push_outbox(recipient_user_id,title,body,event,status,accounting_notification_id,related_entity_id) SELECT recipient_user_id,title,body,event,status,accounting_notification_id,related_entity_id FROM push_outbox WHERE accounting_notification_id IS NOT NULL LIMIT 1','23505'),'unique typed receipt prevents duplicate accounting outbox entries');
SELECT assert_true(refuses('INSERT INTO push_outbox(title,body,event,status,accounting_notification_id,related_entity_id) VALUES(''bad'',''bad'',''accounting_invoice'',''pending'',u(99999),u(99999))','23503'),'typed accounting notification ID has real FK authority');
SELECT assert_true(refuses('UPDATE push_outbox SET related_entity_id=NULL WHERE accounting_notification_id IS NOT NULL','23514'),'typed receipt cannot lose its notification identity through null');
SELECT assert_true(NOT EXISTS(SELECT 1 FROM push_outbox WHERE status='sent'),'native verification never sends a device push');
